const $=s=>document.querySelector(s); const $$=s=>[...document.querySelectorAll(s)];
function readStore(key,fallback){try{const v=localStorage.getItem(key);return v?JSON.parse(v):JSON.parse(JSON.stringify(fallback))}catch{return JSON.parse(JSON.stringify(fallback))}}
function saveStore(key,val){localStorage.setItem(key,JSON.stringify(val))}
const attachmentDb=new Promise((resolve,reject)=>{if(!('indexedDB'in window)){resolve(null);return}const req=indexedDB.open('gridline-field',1);req.onupgradeneeded=()=>{const db=req.result;if(!db.objectStoreNames.contains('attachments'))db.createObjectStore('attachments',{keyPath:'key'})};req.onsuccess=()=>resolve(req.result);req.onerror=()=>resolve(null)});
async function persistAttachments(jobId,files){if(!files.length)return;const db=await attachmentDb;if(!db)return;await new Promise(resolve=>{const tx=db.transaction('attachments','readwrite'),store=tx.objectStore('attachments');files.forEach((file,i)=>store.put({key:`${jobId}:${Date.now()}:${i}`,jobId,name:file.name,type:file.type,blob:file,storedAt:new Date().toISOString()}));tx.oncomplete=resolve;tx.onerror=resolve})}
function esc(s=''){return String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function priorityClass(p){return p.toLowerCase()}
function statusClass(s){return {'Open':'open','In progress':'progress','Completed':'done','Needs review':'review'}[s]||'open'}
function orderRows(list){return list.map(o=>`<tr><td><span class="order-id">${esc(o.id)}</span><span class="order-title">${esc(o.title)}</span></td><td><span class="order-location">${esc(o.location)}</span></td><td><span class="assignee"><i class="assignee-avatar ${esc(o.avatar)}">${esc(o.initials)}</i><span class="assignee-name">${esc(o.assignee)}</span></span></td><td><span class="priority priority-${priorityClass(o.priority)}"><i></i>${esc(o.priority)}</span></td><td><span class="status-tag status-${statusClass(o.status)}">${esc(o.status)}</span></td><td><button class="row-more" data-order="${esc(o.id)}" aria-label="Open ${esc(o.id)}">···</button></td></tr>`).join('')}
function renderOrders(){const priority=['Urgent','High','Medium','Low'];const sorted=[...orders].sort((a,b)=>priority.indexOf(a.priority)-priority.indexOf(b.priority));$('#orders-body').innerHTML=orderRows(sorted.slice(0,5));$('#all-orders-body').innerHTML=orderRows(sorted.filter(o=>selectedFilter==='All'||o.status===selectedFilter));$$('[data-order]').forEach(b=>b.addEventListener('click',()=>openOrder(b.dataset.order)))}
const schedule=[['8:30','Sandeep Reddy','Transformer inspection','Hyderabad · HYD-TF-1042',''],['9:00','Ananya Rao','Power line repair','Ranga Reddy · HYD-FDR-12','a2'],['9:30','Vikram Sharma','Meter replacement','Medchal-Malkajgiri · Route 07','a3'],['10:00','Priya Nair','Substation safety check','Hyderabad · HYD-SS-04','a4']];
function renderSchedule(){$('#schedule-list').innerHTML=schedule.map(([time,name,title,meta,av])=>`<div class="schedule-item"><span class="schedule-time">${time}</span><span class="schedule-track"></span><div class="schedule-info"><strong>${name} <span style="font-weight:400;color:#92a097">· ${title}</span></strong><small>${meta}</small></div></div>`).join('')}
function renderField(){const list=$('#field-jobs');if(!list)return;$('#field-job-count').textContent=fieldJobs.length;$('#my-jobs-stat').textContent=fieldJobs.length;$('#completed-stat').textContent=2+doneJobs.length;list.innerHTML=fieldJobs.map(j=>{const open=expandedJob===j.id;return `<article class="field-job-card"><div class="job-card-main"><span class="job-kind-icon ${j.priority==='High'?'outage':j.kind.includes('inspection')?'inspection':''}">${j.icon}</span><div class="job-copy"><div class="job-topline"><h3>${esc(j.title)}</h3><span class="job-priority ${j.priority==='Routine'?'routine':''}">${esc(j.priority)}</span></div><p>${esc(j.kind)} · ${esc(j.location)}</p><div class="job-meta"><span>${esc(j.customer.split(' · ')[0])}</span><span>${esc(j.id)}</span></div></div><span class="job-time">${esc(j.time)}</span></div><div class="job-card-actions">${j.status==='Open'?`<button class="job-action start" data-start="${j.id}">Start job</button>`:`<button class="job-action primary" data-open-job="${j.id}">Continue</button>`}<button class="job-action" data-open-job="${j.id}">Checklist <span>${j.progress}/${j.total}</span></button><button class="job-expand" data-expand="${j.id}" aria-label="${open?'Collapse':'Expand'} job">${open?'⌃':'⌄'}</button></div>${open?`<div class="job-details"><div class="job-address">${esc(j.location)} <span>↗ Map</span></div><div class="check-progress"><span>Checklist progress</span><span>${j.progress} of ${j.total} complete</span></div><div class="progress-track"><i style="width:${Math.round(j.progress/j.total*100)}%"></i></div><div class="field-detail-actions"><button class="job-action primary" data-open-job="${j.id}">☷ &nbsp;Open checklist</button><button class="job-action" data-photos="${j.id}">▧ &nbsp;Photos${photoCounts[j.id]?` (${photoCounts[j.id]})`:''}</button><button class="job-action" data-open-job="${j.id}">Details →</button></div></div>`:''}</article>`}).join('');$$('[data-expand]').forEach(b=>b.onclick=()=>{expandedJob=expandedJob===b.dataset.expand?null:b.dataset.expand;renderField()});$$('[data-start]').forEach(b=>b.onclick=()=>{const j=fieldJobs.find(x=>x.id===b.dataset.start);j.status='In progress';if(!j.startedAt)j.startedAt=new Date().toISOString();queueChange(j.id,'Job started');saveField();renderField();toast('Job started',j.title)});$$('[data-open-job]').forEach(b=>b.onclick=()=>openJobChecklist(b.dataset.openJob));$$('[data-photos]').forEach(b=>b.onclick=()=>openJobChecklist(b.dataset.photos,true));renderHistory()}
function renderHistory(){const box=$('#history-list');if(!box)return;const base=[{title:'Service restoration',location:'Secunderabad, Hyderabad',time:'Today · 8:12 AM'},{title:'Switchgear thermal scan',location:'Balanagar Industrial Area, Hyderabad',time:'Friday · 3:45 PM'},...doneJobs.map(d=>({title:d.title,location:d.location,time:'Today · just now'}))];box.innerHTML=base.map(x=>`<div class="history-row"><div><strong>${esc(x.title)}</strong><small>${esc(x.location)} · ${esc(x.time)}</small></div><span>✓ Complete</span></div>`).join('')}
function saveField(){saveStore('gridline-jobs',fieldJobs);saveStore('gridline-pending',changes);saveStore('gridline-done',doneJobs);saveStore('gridline-photo-counts',photoCounts);updateConnection()}
function online(){return navigator.onLine&&!forcedOffline}
function updateConnection(){const offline=!online();['#connection-status','#field-connection'].forEach(sel=>{const e=$(sel);if(!e)return;e.classList.toggle('offline',offline);const label=e.querySelector('span:last-child');if(label)label.textContent=offline?'Offline mode':'Connected'});const msg=$('#sync-message');if(msg){msg.textContent=offline?`${changes.length} change${changes.length===1?'':'s'} saved on device`:changes.length?`${changes.length} change${changes.length===1?'':'s'} waiting to sync`:'All changes synced';const dot=msg.parentElement.querySelector('.sync-indicator');dot?.classList.toggle('pending',offline||changes.length>0)}}
function queueChange(id,description){changes.push({id,description,at:new Date().toISOString()});saveField();if(online())setTimeout(syncChanges,350)}
function syncChanges(){if(!online()||!changes.length)return;const n=changes.length;changes=[];saveField();toast('Updates synced',`${n} field update${n===1?'':'s'} saved`)}
function toast(msg,detail=''){const t=document.createElement('div');t.className='toast';t.innerHTML=`${esc(msg)}${detail?`<small>${esc(detail)}</small>`:''}`;$('#toast-region').appendChild(t);setTimeout(()=>t.remove(),3600)}
function switchPage(page){const field=page==='field';$('#field-page').classList.toggle('hidden',!field);$('#overview-page').classList.toggle('hidden',field||page!=='overview');$('#work-orders-page').classList.toggle('hidden',field||page!=='work-orders');$('#breadcrumb-current').textContent=field?'Field mode':page==='work-orders'?'Work orders':'Overview';$$('.nav-item').forEach(b=>b.classList.toggle('active',b.dataset.page===page));if(field){renderField();updateConnection()}window.scrollTo(0,0)}
function openOrder(id){const o=orders.find(x=>x.id===id);if(!o)return;$('#modal-title').textContent=o.title;$('#modal-content').innerHTML=`<div class="modal-content"><div class="modal-work-meta"><span>${esc(o.id)}</span><span>${esc(o.district)} District</span><b>${esc(o.priority)} priority</b></div><p class="modal-description">${o.title==='Transformer inspection'?'Complete the scheduled visual inspection for transformer HYD-TF-1042. Record oil level, temperature, bushing condition, and any visible leaks.':o.title==='Power line repair'?'Investigate a reported conductor fault on Feeder 12. Confirm the circuit is safe to access, repair the damaged span, and document restoration.':'Review this service request, verify equipment condition, and record any work performed.'}</p><div><span class="assignee"><i class="assignee-avatar ${esc(o.avatar)}">${esc(o.initials)}</i><span class="assignee-name">${esc(o.assignee)}</span></span><span style="margin-left:18px;color:#839087;font-size:9px">⌖ ${esc(o.location)}</span></div><h3 class="checklist-title">Work summary</h3><p style="font-size:10px;color:#7d8b83;line-height:1.6">Field updates, inspection results, and attachments are stored on this work order. Technician changes sync when a connection is available.</p><div class="modal-actions"><button class="button button-secondary" id="modal-close-2">Close</button><div class="modal-right-actions"><button class="button button-primary" id="assign-open">↗ &nbsp;Assign technician</button></div></div></div>`;showModal();$('#modal-close-2').onclick=hideModal;$('#assign-open').onclick=()=>{hideModal();openNewOrder(o)} }
function openNewOrder(source){$('#modal-title').textContent=source?'Assign technician':'Create work order';$('#modal-content').innerHTML=`<form class="new-order-form" id="new-order-form"><label class="modal-field-label">WORK ORDER TITLE</label><input class="modal-input" name="title" required placeholder="e.g. Transformer inspection" value="${source?esc(source.title):''}"/><label class="modal-field-label">SERVICE LOCATION</label><input class="modal-input" name="location" required placeholder="Street address or asset ID" value="${source?esc(source.location):''}"/><label class="modal-field-label">ASSIGN TECHNICIAN</label><select class="modal-select" name="assignee"><option>Vikram Sharma</option><option>Sandeep Reddy</option><option>Ananya Rao</option><option>Priya Nair</option><option>Unassigned</option></select><label class="modal-field-label">PRIORITY</label><select class="modal-select" name="priority"><option>Medium</option><option>High</option><option>Urgent</option><option>Low</option></select><label class="modal-field-label">WORK NOTES</label><textarea class="modal-textarea" name="notes" placeholder="Describe the issue or required inspection"></textarea><div class="modal-actions"><button type="button" class="button button-secondary" id="modal-cancel">Cancel</button><button class="button button-primary" type="submit">${source?'Save assignment':'Create work order'}</button></div></form>`;showModal();$('#modal-cancel').onclick=hideModal;$('#new-order-form').onsubmit=e=>{e.preventDefault();const f=new FormData(e.currentTarget);if(source){source.assignee=f.get('assignee');source.priority=f.get('priority');source.status='Open';renderOrders();queueChange(source.id,'Assignment updated');toast('Assignment updated',source.id)}else{const id=`WO-${Math.floor(2860+Math.random()*100)}`,assignee=f.get('assignee');const person={ 'Vikram Sharma':['VS','a3'],'Sandeep Reddy':['SR',''],'Ananya Rao':['AR','a2'],'Priya Nair':['PN','a4'],'Unassigned':['—','a5']}[assignee];orders.unshift({id,title:f.get('title'),location:f.get('location'),district:'Hyderabad',assignee,initials:person[0],avatar:person[1],priority:f.get('priority'),status:'Open',icon:'▤'});renderOrders();toast('Work order created',id)}hideModal()}}
function openJobChecklist(id,focusPhotos=false){const j=fieldJobs.find(x=>x.id===id);if(!j)return;currentWorkId=id;localPhotos=[];$('#modal-title').textContent=j.title;const items=j.checklist.map((label,i)=>`<label class="checklist-row"><input type="checkbox" data-check-index="${i}" ${i<j.progress?'checked':''}><span>${esc(label)}</span>${i===0?'<span class="check-note">Required</span>':''}</label>`).join('');$('#modal-content').innerHTML=`<div class="modal-content"><div class="modal-work-meta"><span>${esc(j.id)}</span><span>${esc(j.kind)}</span><b>${esc(j.priority)} priority</b></div><p class="modal-description">${esc(j.description)}</p><h3 class="checklist-title">Inspection checklist <span style="font-weight:400;color:#8c9991">· <span id="check-count">${j.progress}/${j.total}</span></span></h3><div class="checklist-items">${items}</div><label class="job-note-label" for="job-note">FIELD NOTES</label><textarea class="job-notes" id="job-note" placeholder="Add observations, readings, or parts used…">${esc(j.notes||'')}</textarea><div class="attachment-strip" id="attachment-strip">${(photoCounts[id]||0)>0?Array.from({length:photoCounts[id]},(_,i)=>`<span class="photo-preview">▧<small>Photo ${i+1}</small></span>`).join(''):''}</div><div class="modal-actions"><label class="photo-button" for="photo-input">▧ &nbsp;Add photo <span class="photo-count">${photoCounts[id]?`(${photoCounts[id]})`:''}</span></label><input id="photo-input" type="file" accept="image/*" capture="environment" multiple hidden><div class="modal-right-actions"><button class="button button-secondary" id="save-progress">Save progress</button><button class="button button-primary" id="complete-job">Complete job</button></div></div></div>`;showModal();if(focusPhotos)$('#photo-input').click();const updateCount=()=>{$('#check-count').textContent=`${$$('[data-check-index]:checked').length}/${j.total}`};$$('[data-check-index]').forEach(c=>c.addEventListener('change',updateCount));$('#photo-input').onchange=e=>{localPhotos=[...e.target.files].map(f=>({name:f.name,type:f.type,size:f.size}));const strip=$('#attachment-strip');localPhotos.forEach((f,i)=>{const n=document.createElement('span');n.className='photo-preview';n.textContent='▧';const label=document.createElement('small');label.textContent=`Photo ${i+1}`;n.appendChild(label);strip.appendChild(n)});$('#modal-content .photo-count').textContent=`(${(photoCounts[id]||0)+localPhotos.length})`;if(localPhotos.length)toast('Photos attached',`${localPhotos.length} image${localPhotos.length===1?'':'s'} ready to sync`)};$('#save-progress').onclick=()=>saveJobProgress(j,false);$('#complete-job').onclick=()=>saveJobProgress(j,true)}
async function saveJobProgress(j,complete){j.progress=$$('[data-check-index]:checked').length;j.notes=$('#job-note').value.trim();if(localPhotos.length){const adding=[...localPhotos];await persistAttachments(j.id,adding);photoCounts[j.id]=(photoCounts[j.id]||0)+adding.length;j.photoMetadata=[...(j.photoMetadata||[]),...adding.map(f=>({name:f.name,type:f.type,size:f.size,storedLocally:true}))];localPhotos=[]}if(complete||j.progress===j.total){j.status='Completed';fieldJobs=fieldJobs.filter(x=>x.id!==j.id);doneJobs.push({title:j.title,location:j.location,id:j.id});orders=orders.map(o=>o.id===j.id?{...o,status:'Completed'}:o);saveStore('gridline-orders',orders);renderOrders();renderField();hideModal();queueChange(j.id,'Work order completed');toast('Work order completed',j.id);return}j.status='In progress';queueChange(j.id,`Checklist updated · ${j.progress}/${j.total}`);saveField();renderField();hideModal();toast('Progress saved',`${j.progress} of ${j.total} checkpoints complete`)}
function showModal(){$('#modal-backdrop').classList.remove('hidden')}function hideModal(){$('#modal-backdrop').classList.add('hidden');currentWorkId=null}
function setFieldTab(tab){activeFieldTab=tab;$$('.field-tab').forEach(b=>b.classList.toggle('active',b.dataset.fieldTab===tab));$('#field-jobs').classList.toggle('hidden',tab!=='jobs');$('#field-history').classList.toggle('hidden',tab!=='history');$('#field-checklists').classList.toggle('hidden',tab!=='checklists');$('.field-section-title').classList.toggle('hidden',tab!=='jobs')}
function exportReport(){const rows=[['Work order','Title','Location','Assignee','Priority','Status'],...orders.map(o=>[o.id,o.title,o.location,o.assignee,o.priority,o.status])];const csv=rows.map(r=>r.map(c=>'"'+String(c).replace(/"/g,'""')+'"').join(',')).join('\n');const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([csv],{type:'text/csv'}));a.download='gridline-work-orders-2026-11-23.csv';a.click();URL.revokeObjectURL(a.href);toast('Report exported','Work orders CSV downloaded')}
function init(){renderOrders();renderSchedule();renderField();updateConnection();$$('.nav-item').forEach(b=>b.addEventListener('click',()=>{const page=b.dataset.page;if(page==='overview'||page==='work-orders'){switchPage(page);return}if(page==='inspections'){switchPage('field');setFieldTab('checklists');return}if(page==='reports'){exportReport();return}switchPage('overview');toast(page==='crew'?'Crew & schedule':'Assets','Overview includes today’s crew and district activity')}));$('#all-orders-link').onclick=()=>switchPage('work-orders');$('#open-field-mode').onclick=()=>switchPage('field');$('#back-dashboard').onclick=()=>switchPage('overview');$('#new-order-button').onclick=()=>openNewOrder();$('#new-order-button-2').onclick=()=>openNewOrder();$('#export-button').onclick=exportReport;$('#modal-close').onclick=hideModal;$('#modal-backdrop').addEventListener('click',e=>{if(e.target.id==='modal-backdrop')hideModal()});document.addEventListener('keydown',e=>{if(e.key==='Escape')hideModal()});$$('.filter-tabs button').forEach(b=>b.onclick=()=>{$$('.filter-tabs button').forEach(x=>x.classList.remove('selected'));b.classList.add('selected');selectedFilter=b.dataset.filter;renderOrders()});$$('.field-tab').forEach(b=>b.onclick=()=>setFieldTab(b.dataset.fieldTab));$('#notifications-button').onclick=()=>{ $('#modal-title').textContent='Notifications';$('#modal-content').innerHTML='<div class="notification-list"><div class="notification-item">SLA watch · WO-2839 is approaching its response target.<small>12 minutes ago · Ranga Reddy District</small></div><div class="notification-item">Crew update · Sandeep Reddy completed her morning inspection.<small>38 minutes ago · Hyderabad District</small></div><div class="notification-item">Schedule change · Ananya Rao is available for reassignment.<small>1 hour ago · Ranga Reddy District</small></div></div>';showModal()};$('#schedule-link').onclick=()=>{switchPage('overview');toast('Crew schedule','Today’s crew assignments are shown in the schedule panel')};$('#district-link').onclick=()=>{switchPage('work-orders');toast('District breakdown','Filter work orders by district')};$('#schedule-menu').onclick=()=>toast('Schedule options','Showing today’s active crew');$('#range-button').onclick=()=>toast('Operations overview','Showing today’s service activity');$('#date-button').onclick=()=>toast('Current date','Monday, November 23, 2026');$('#filter-button').onclick=()=>toast('Work order filters','Choose a status using the tabs');$$('.pagination button:not(:disabled)').forEach(b=>b.onclick=()=>toast('Work orders',`Page ${b.textContent.trim()}`));$$('.checklist-template').forEach(b=>b.onclick=()=>{const name=b.dataset.template;const job={id:`INSP-${Date.now().toString().slice(-4)}`,title:name,kind:'Inspection checklist',location:'Select an asset',customer:'Field inspection',time:'Anytime',priority:'Routine',status:'Open',progress:0,total:name==='Transformer inspection'?12:name==='Pole safety assessment'?9:7,icon:'☷',description:`Offline-ready ${name.toLowerCase()} form. Check each item, add field notes, and capture photos as needed.`,checklist:Array.from({length:name==='Transformer inspection'?12:name==='Pole safety assessment'?9:7},(_,i)=>`Inspection checkpoint ${i+1} — record condition and observations`)};fieldJobs.unshift(job);saveField();renderField();setFieldTab('jobs');expandedJob=job.id;renderField();openJobChecklist(job.id)});$('#field-sort').onclick=()=>{fieldJobs.sort((a,b)=>(a.priority==='High'?-1:1)-(b.priority==='High'?-1:1));renderField();toast('Jobs sorted','High priority work first')};$('#connection-status').onclick=()=>{forcedOffline=!forcedOffline;updateConnection();toast(forcedOffline?'Offline mode enabled':'Back online',forcedOffline?'Changes will stay on this device':'Syncing queued field updates');if(online())syncChanges()};$('#field-connection').onclick=()=>$('#connection-status').click();window.addEventListener('online',()=>{updateConnection();syncChanges()});window.addEventListener('offline',updateConnection);if('serviceWorker'in navigator)navigator.serviceWorker.register('./sw.js').catch(()=>{});}
init();
